import heapq

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements Dijkstra's algorithm to find the shortest path and distance from the start node to the end node
    in a weighted directed graph represented as an adjacency list.
    """
    min_heap = [(0, start)]
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous_nodes = {node: None for node in graph}

    while min_heap:
        current_distance, current_node = heapq.heappop(min_heap)

        if current_node == end:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = previous_nodes[current_node]
            path.reverse()
            return (current_distance, path)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(min_heap, (distance, neighbor))

    return (float('inf'), [])

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements the Bellman-Ford algorithm to find the shortest path and distance from the start node to the end node
    in a weighted directed graph represented as an adjacency list. This algorithm can handle negative weights.
    """
    # Step 1: Initialize distances from start to all other nodes as infinity and distance to start itself as 0
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    predecessor = {node: None for node in graph}

    # Step 2: Relax edges repeatedly
    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    predecessor[neighbor] = node

    # Step 3: Check for negative weight cycles (not strictly needed for this task)
    for node in graph:
        for neighbor, weight in graph[node]:
            if distances[node] + weight < distances[neighbor]:
                raise ValueError("Graph contains a negative weight cycle")

    # Step 4: Reconstruct path
    if distances[end] == float('inf'):
        return (float('inf'), [])

    path = []
    current_node = end
    while current_node is not None:
        path.append(current_node)
        current_node = predecessor[current_node]
    path.reverse()

    return (distances[end], path)

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements the A* algorithm to find the shortest path and distance from the start node to the end node
    in a weighted directed graph represented as an adjacency list. This algorithm uses heuristics to improve performance.
    """
    import heapq

    def heuristic(node: str) -> float:
        return 0  # For simplicity, a zero heuristic (Dijkstra's behaviour)

    open_set = [(0 + heuristic(start), 0, start)]
    came_from = {}
    g_score = {node: float('inf') for node in graph}
    g_score[start] = 0

    while open_set:
        _, current_g, current = heapq.heappop(open_set)

        if current == end:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            path.reverse()
            return (current_g, path)

        for neighbor, weight in graph[current]:
            tentative_g_score = current_g + weight
            if tentative_g_score < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g_score
                heapq.heappush(open_set, (tentative_g_score + heuristic(neighbor), tentative_g_score, neighbor))

    return (float('inf'), [])

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements the BFS-based algorithm with a queue to find the shortest path in an unweighted or uniformly weighted graph
    transformed by normalizing weights. This approach is primarily effective for graphs without varying edge weights.
    """
    from collections import deque

    if start == end:
        return (0, [start])

    queue = deque([(start, 0)])  # (current_node, current_distance)
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous_nodes = {node: None for node in graph}

    while queue:
        current_node, current_distance = queue.popleft()

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                queue.append((neighbor, distance))

    if distances[end] == float('inf'):
        return (float('inf'), [])

    path = []
    current_node = end
    while current_node is not None:
        path.append(current_node)
        current_node = previous_nodes[current_node]
    path.reverse()

    return (distances[end], path)

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements the Floyd-Warshall algorithm to find the shortest path and distances between all pairs of nodes
    in a weighted directed graph represented as an adjacency list. This algorithm works well for dense graphs.
    """
    # Initialize distance and path matrices
    nodes = list(graph.keys())
    num_nodes = len(nodes)
    distances = {node: {other: float('inf') for other in nodes} for node in nodes}
    next_node = {node: {other: None for other in nodes} for node in nodes}

    for node in nodes:
        distances[node][node] = 0

    for node in graph:
        for neighbor, weight in graph[node]:
            distances[node][neighbor] = weight
            next_node[node][neighbor] = neighbor

    # Floyd-Warshall algorithm
    for k in nodes:
        for i in nodes:
            for j in nodes:
                if distances[i][j] > distances[i][k] + distances[k][j]:
                    distances[i][j] = distances[i][k] + distances[k][j]
                    next_node[i][j] = next_node[i][k]

    # Reconstruct the path from start to end
    if distances[start][end] == float('inf'):
        return (float('inf'), [])

    path = []
    current = start
    while current is not None:
        path.append(current)
        if current == end:
            break
        current = next_node[current][end]

    return (distances[start][end], path)
